/**
 * KeyMask Ephemeral Clipboard Architecture
 *
 * Requirements:
 * - Decryption on Demand: transfers decrypted text directly to OS clipboard.
 * - Volatile Metadata Flags (Desktop / Electron): writes clipboard payload
 *   with platform-specific exclusion flags:
 *     macOS: org.nspasteboard.ConcealedType and org.nspasteboard.AutoGeneratedType
 *     Windows: ExcludeClipboardContentFromMonitorProcessing
 * - Auto-Wipe Timer: Triggers after N seconds (default 30s).
 *   If clipboard still matches the secret, overwrites with empty text.
 */

import { Notice } from "obsidian";

export interface ClipboardOptions {
  timeoutSeconds?: number;
  notifyOnWipe?: boolean;
}

interface ElectronClipboard {
  readText(): string;
  writeText(text: string): void;
  clear(): void;
}

interface ElectronModule {
  clipboard?: ElectronClipboard;
}

export class KeyMaskClipboard {
  private static activeWipeTimer: ReturnType<typeof setTimeout> | null = null;
  private static lastSecretCopied: string | null = null;

  /**
   * Safely obtain Electron clipboard module if running in Obsidian Desktop
   */
  private static getElectronClipboard(): ElectronClipboard | null {
    try {
      if (typeof window !== "undefined") {
        const req = (window as unknown as { require?: (mod: string) => unknown }).require;
        if (typeof req === "function") {
          const electron = req("electron") as ElectronModule | undefined;
          return electron?.clipboard || null;
        }
      }
    } catch (_err) {
      void _err;
    }
    return null;
  }

  /**
   * Reads current text from clipboard
   */
  public static async readText(): Promise<string | null> {
    const electronClipboard = this.getElectronClipboard();
    if (electronClipboard) {
      try {
        return electronClipboard.readText();
      } catch (_err) {
        void _err;
      }
    }

    if (
      typeof navigator !== "undefined" &&
      navigator.clipboard &&
      navigator.clipboard.readText
    ) {
      try {
        return await navigator.clipboard.readText();
      } catch (_err) {
        void _err;
      }
    }

    return null;
  }

  /**
   * Overwrite clipboard with empty string
   */
  public static async clearClipboard(): Promise<void> {
    const electronClipboard = this.getElectronClipboard();
    if (electronClipboard) {
      try {
        electronClipboard.clear();
        return;
      } catch (_err) {
        void _err;
      }
    }

    if (
      typeof navigator !== "undefined" &&
      navigator.clipboard &&
      navigator.clipboard.writeText
    ) {
      try {
        await navigator.clipboard.writeText("");
      } catch {
        // Fall through
      }
    }
  }

  /**
   * Write sensitive secret to clipboard with volatile exclusion flags
   * and schedule ephemeral auto-wipe.
   */
  public static async writeSecret(
    secret: string,
    options: ClipboardOptions = {}
  ): Promise<void> {
    const timeoutSeconds = options.timeoutSeconds ?? 30;
    const notifyOnWipe = options.notifyOnWipe ?? true;

    // 1. Clear any prior auto-wipe timer
    if (this.activeWipeTimer !== null) {
      window.clearTimeout(this.activeWipeTimer);
      this.activeWipeTimer = null;
    }
    this.lastSecretCopied = secret;

    // Write text to clipboard across desktop and mobile
    await this.writeText(secret);

    // 2. Schedule Ephemeral Auto-Wipe Timer
    if (timeoutSeconds > 0) {
      this.activeWipeTimer = window.setTimeout(() => {
        void (async () => {
          try {
            // Verify if clipboard still contains this exact secret before wiping
            const currentText = await this.readText();
            if (currentText === this.lastSecretCopied) {
              await this.clearClipboard();
              this.lastSecretCopied = null;
              if (notifyOnWipe) {
                new Notice("🔒 KeyMask: Ephemeral clipboard cleared for security.");
              }
            }
          } catch (e) {
            console.warn("KeyMask: Ephemeral clipboard wipe encountered error:", e);
          } finally {
            this.activeWipeTimer = null;
          }
        })();
      }, timeoutSeconds * 1000);
    }
  }

  /**
   * Write plain text to clipboard directly without auto-wipe (for ciphertext, tokens, etc.)
   */
  public static async writeText(text: string): Promise<void> {
    const electronClipboard = this.getElectronClipboard();
    let written = false;

    if (electronClipboard) {
      try {
        electronClipboard.writeText(text);
        written = true;
      } catch (err) {
        console.warn("KeyMask: Electron writeText failed, falling back to navigator", err);
      }
    }

    if (!written) {
      if (
        typeof navigator !== "undefined" &&
        navigator.clipboard &&
        navigator.clipboard.writeText
      ) {
        try {
          await navigator.clipboard.writeText(text);
          written = true;
        } catch (clipErr) {
          console.warn("KeyMask: navigator.clipboard.writeText failed, trying execCommand fallback", clipErr);
        }
      }
    }

    if (!written) {
      // Fallback for iOS/mobile webviews where navigator.clipboard requires direct sync user gesture
      try {
        const textArea = createEl("textarea");
        textArea.value = text;
        textArea.className = "keymask-offscreen-textarea";
        textArea.setAttribute("readonly", "");
        const doc = typeof activeDocument !== "undefined" ? activeDocument : document;
        doc.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        textArea.setSelectionRange(0, text.length);
        const success = doc.execCommand("copy");
        doc.body.removeChild(textArea);
        if (!success) {
          throw new Error("execCommand copy returned false");
        }
        written = true;
      } catch {
        throw new Error("Unable to access clipboard in this environment.");
      }
    }
  }

  /**
   * Cancel active auto-wipe timer
   */
  public static cancelAutoWipe(): void {
    if (this.activeWipeTimer !== null) {
      window.clearTimeout(this.activeWipeTimer);
      this.activeWipeTimer = null;
      this.lastSecretCopied = null;
    }
  }
}
